"""Preserve XML text carriage returns with the safe stdlib spreadsheet writer."""

from pathlib import Path
from zipfile import ZIP_DEFLATED, ZipFile, ZipInfo

from openpyxl.writer.excel import ExcelWriter


class _SpreadsheetArchive(ZipFile):
    # ElementTree emits literal CR in text, which XML readers normalize to LF.
    # This archive only receives XML generated by pinned openpyxl/et_xmlfile:
    # attributes are already escaped and markup uses LF, so remaining CR bytes
    # are text values and must use a character reference to survive a roundtrip.
    # No user-provided archive is accepted and no global parser is patched.
    def writestr(self, zinfo_or_arcname, data, compress_type=None, compresslevel=None):
        name = zinfo_or_arcname.filename if isinstance(zinfo_or_arcname, ZipInfo) else zinfo_or_arcname
        if name.endswith((".xml", ".rels")):
            if isinstance(data, str):
                data = data.encode("utf-8")
            data = data.replace(b"\r", b"&#13;")
        return super().writestr(zinfo_or_arcname, data, compress_type=compress_type, compresslevel=compresslevel)

    def write(self, filename, arcname=None, compress_type=None, compresslevel=None):
        name = str(arcname) if arcname is not None else str(filename)
        if not name.endswith((".xml", ".rels")):
            return super().write(filename, arcname, compress_type=compress_type, compresslevel=compresslevel)
        info = ZipInfo.from_file(filename, arcname)
        info.compress_type = self.compression if compress_type is None else compress_type
        info._compresslevel = self.compresslevel if compresslevel is None else compresslevel
        with Path(filename).open("rb") as source, self.open(info, "w", force_zip64=True) as output:
            while chunk := source.read(65536):
                output.write(chunk.replace(b"\r", b"&#13;"))


def save_xlsx(workbook, output):
    """Use the normal Excel writer with a streaming CR-preserving XML archive."""
    with _SpreadsheetArchive(output, "w", compression=ZIP_DEFLATED, allowZip64=True) as archive:
        ExcelWriter(workbook, archive).save()
